```java
public static int fee(int minutes) {
    if (minutes <= 20) {
        return 0;
    }
    int hours = (minutes + 59) / 60;
    int cost = hours * 5;
    if (cost > 40) {
        cost = 40;
    }
    return cost;
}
```

```java
public static int longestStay(int budget) {
    for (int m = 1440; m >= 0; m--) {
        if (fee(m) <= budget) {
            return m;
        }
    }
    return 0;
}
```

```java
public class PunchCard {
    private int remaining;
    private int punches;
    public PunchCard(int visits) {
        remaining = visits;
        punches = 0;
    }
    public boolean punch() {
        if (remaining == 0) {
            return false;
        }
        remaining--;
        punches++;
        if (punches % 3 == 0) {
            remaining++;
        }
        return true;
    }
    public int getRemaining() {
        return remaining;
    }
}
```

```java
public int revenue() {
